print(loss(2))  # one input in, one number out

def loss(w):
    return (w - 3) ** 2

for w in [0, 2, 3, 5]:
    print(w, loss(w))   # 0 9 / 2 1 / 3 0 / 5 4

def loss(w):
    return (w - 3) ** 2

print(loss(2.0), loss(2.5))   # 1.0 0.25: a small change

def step_rule(w):
    return 0 if w < 2 else 1

print(step_rule(1.999), step_rule(2.0))   # 0 1: a jump

def loss(w):
    return (w - 3) ** 2

w = 1.0
for _ in range(3):
    w = w + 0.5          # small steps change the loss smoothly
    print(w, loss(w))
